/**
 * PARTNER GAME-SERVER GRANTS (plain server module — callers do their own auth).
 *
 * An admin grants a creator partner a free game server so they can try the
 * product before promoting it. The server is a NORMAL Server row created by the
 * same `placeGameOrder` every customer order goes through (so capacity checks,
 * config validation, node scheduling, invoice, audit and provisioning are the
 * real ones) with a sold price of 0 — `isFree` is deliberately NOT set, because
 * isFree means "no billing, ever".
 *
 * EXPIRY — explicit, per grant (PartnerGrant.onExpiry):
 *   EXPIRE (default)  Server.autoRenew is switched OFF at grant time. When the
 *                     term ends the ordinary no-renewal lifecycle applies
 *                     (suspend, then removal after the grace period) — nothing is
 *                     ever charged. The partner can renew it at the normal price
 *                     from their wallet any time (that flips the grant to
 *                     CONVERTED), and gets a 7-day and a 1-day notice first.
 *   RENEW_WALLET      autoRenew stays ON: at term end the normal renewal sweep
 *                     charges the normal price (wallet first, then a saved card if
 *                     the account has one), exactly as for any customer. Chosen
 *                     deliberately by the admin, and the partner is told in the
 *                     7-day and 1-day notices what will be charged and when.
 * A grant never makes a server free forever and never charges anyone without
 * having been announced in writing first.
 */
import type { User } from "@prisma/client";
import { db } from "./db";
import { placeGameOrder, gameOrderGate, gameOrderQuote, GameOrderError, type GameOrderIntent } from "./game-order";
import { schemaFor } from "./game-config";
import { PRODUCT_TERMS } from "./billing-terms";

import { grantPhase } from "./partner-grant-rules";
export { GRANT_NOTICE_DAYS, GRANT_FINAL_NOTICE_DAYS, grantPhase } from "./partner-grant-rules";
export const MAX_ACTIVE_GRANTS_PER_PARTNER = 3;
export type GrantPolicy = "EXPIRE" | "RENEW_WALLET";

export type GrantInput = {
  partnerId: string;
  gamePlanId: string;
  termMonths: number;
  region?: string;
  variant?: string;
  config?: Record<string, unknown>;
  subdomain?: string;
  hostname?: string;
  serverName?: string;
  reason: string;
  onExpiry: GrantPolicy;
};

export function validGrantTerm(m: number): boolean {
  return PRODUCT_TERMS.some((t) => t.months === m);
}

export type GrantResult = { ok: true; grantId: string; serverId: string; expiresAt: Date } | { ok: false; error: string };

/** The wording of an expiry policy, shown wherever a grant is shown. */
export function policyText(p: string, expiresAt: Date | null): string {
  const when = expiresAt ? expiresAt.toISOString().slice(0, 10) : "the end of the term";
  return p === "RENEW_WALLET"
    ? `Renews at the normal price on ${when} (wallet, then saved card) — the partner is warned 7 and 1 days before.`
    : `Ends on ${when}: auto-renew is off, so the server is suspended at term end (no charge) unless the partner renews it.`;
}

export async function grantPartnerServer(input: GrantInput, actor: { id: string; email?: string }): Promise<GrantResult> {
  const fail = async (error: string): Promise<GrantResult> => {
    await db.auditLog.create({ data: { userId: actor.id, action: "partner.grant_failed", detail: `partner=${input.partnerId} plan=${input.gamePlanId} error=${error.slice(0, 200)}` } });
    return { ok: false, error };
  };
  const reason = (input.reason ?? "").trim();
  if (reason.length < 3 || reason.length > 300) return { ok: false, error: "Give a short reason (3–300 characters) — it's kept in the audit trail." };
  if (!validGrantTerm(input.termMonths)) return { ok: false, error: "Pick a valid term." };
  if (input.onExpiry !== "EXPIRE" && input.onExpiry !== "RENEW_WALLET") return { ok: false, error: "Choose what happens when the term ends." };

  const partner = await db.referralPartner.findUnique({ where: { id: input.partnerId }, include: { user: true } });
  if (!partner) return { ok: false, error: "Partner not found." };
  if (partner.status !== "ACTIVE") return { ok: false, error: "That partner is paused — activate them first." };
  if (!partner.user) return { ok: false, error: "This partner has no linked account to host the server on. They need to claim their invite / sign in first." };
  const user = partner.user as User;

  const active = await db.partnerGrant.count({ where: { partnerId: partner.id, status: { in: ["ACTIVE", "EXPIRING"] } } });
  if (active >= MAX_ACTIVE_GRANTS_PER_PARTNER) return { ok: false, error: `This partner already has ${active} active grants (max ${MAX_ACTIVE_GRANTS_PER_PARTNER}). Revoke or let one lapse first.` };

  const gate = await gameOrderGate(user);
  if (gate) return fail(gate);

  const gp = await db.gamePlan.findUnique({ where: { id: input.gamePlanId }, select: { gameFamily: true, name: true } });
  if (!gp) return { ok: false, error: "Game plan not found." };

  const intent: GameOrderIntent = {
    gamePlanId: input.gamePlanId, termMonths: input.termMonths,
    serverName: input.serverName?.trim() || `${partner.name} (Nxeon partner)`.slice(0, 60),
    hostname: input.hostname?.trim().toLowerCase() || undefined,
    variant: input.variant || undefined,
    subdomain: input.subdomain?.trim().toLowerCase() || undefined,
    region: input.region || undefined,
    config: input.config ?? null,
    dedicatedIp: false,
  };

  // Validate everything BEFORE placing (clear errors, no half-made server): the quote runs the
  // same schema/subdomain/plan checks the real order does and touches nothing.
  try {
    await gameOrderQuote(intent, { userId: user.id });
  } catch (e) {
    return fail(e instanceof GameOrderError ? e.message : "That configuration isn't valid.");
  }

  let serverId: string;
  try {
    // Sold at 0 with NO partner discount tier: never consumes the partner's own first-purchase slot.
    serverId = await placeGameOrder(user, intent, { chargeCents: 0, partnerDiscountCents: 0, partnerDiscountTier: "NONE" });
  } catch (e) {
    const msg = e instanceof GameOrderError ? e.message : "The server could not be created.";
    if (!(e instanceof GameOrderError)) console.error("[partner-grant] placeGameOrder failed", e);
    return fail(msg);
  }

  const server = await db.server.findUnique({ where: { id: serverId }, select: { expiresAt: true } });
  const expiresAt = server?.expiresAt ?? null;
  try {
    const grant = await db.$transaction(async (tx) => {
      await tx.server.update({ where: { id: serverId }, data: { autoRenew: input.onExpiry === "RENEW_WALLET" } });
      return tx.partnerGrant.create({
        data: {
          partnerId: partner.id, serverId, grantedById: actor.id, reason, game: gp.gameFamily, planName: gp.name,
          termMonths: input.termMonths, region: input.region ?? null, expiresAt, onExpiry: input.onExpiry, status: "ACTIVE",
        },
      });
    });
    await db.auditLog.create({
      data: { userId: actor.id, action: "partner.grant_server", detail: `grant=${grant.id} partner=${partner.id} server=${serverId} game=${gp.gameFamily} plan=${gp.name} term=${input.termMonths}mo onExpiry=${input.onExpiry} reason=${reason.slice(0, 120)}` },
    });
    return { ok: true, grantId: grant.id, serverId, expiresAt: expiresAt ?? new Date() };
  } catch (e) {
    // The server exists but the record failed: make sure it can never auto-charge, then say so loudly.
    await db.server.update({ where: { id: serverId }, data: { autoRenew: false } }).catch(() => {});
    console.error("[partner-grant] grant row failed after server creation", serverId, e);
    return fail(`Server ${serverId} was created but recording the grant failed — auto-renew was switched off on it. Check the server list.`);
  }
}

/** Switch what happens at expiry (also flips the server's autoRenew to match). */
export async function setGrantPolicy(grantId: string, policy: GrantPolicy, actorId: string): Promise<{ error?: string }> {
  const g = await db.partnerGrant.findUnique({ where: { id: grantId } });
  if (!g) return { error: "Grant not found." };
  if (g.status !== "ACTIVE" && g.status !== "EXPIRING") return { error: `A ${g.status.toLowerCase()} grant can't be changed.` };
  if (g.serverId) await db.server.update({ where: { id: g.serverId }, data: { autoRenew: policy === "RENEW_WALLET" } });
  // Changing the policy restarts the notice clock so the partner is warned about the NEW behaviour.
  await db.partnerGrant.update({ where: { id: g.id }, data: { onExpiry: policy, noticeSentAt: null, finalNoticeSentAt: null } });
  await db.auditLog.create({ data: { userId: actorId, action: "partner.grant_policy", detail: `grant=${g.id} onExpiry=${policy}` } });
  return {};
}

/** Revoke = stop it renewing and mark it; the server runs out its paid term (we never delete customer data from here). */
export async function revokeGrant(grantId: string, actorId: string): Promise<{ error?: string }> {
  const g = await db.partnerGrant.findUnique({ where: { id: grantId } });
  if (!g) return { error: "Grant not found." };
  if (g.status === "REVOKED") return {};
  if (g.serverId) await db.server.update({ where: { id: g.serverId }, data: { autoRenew: false } });
  await db.partnerGrant.update({ where: { id: g.id }, data: { status: "REVOKED" } });
  await db.auditLog.create({ data: { userId: actorId, action: "partner.grant_revoke", detail: `grant=${g.id} server=${g.serverId}` } });
  return {};
}

// ---------- lifecycle sweep (worker, hourly) ----------

export async function partnerGrantSweep(now = new Date()): Promise<{ notices: number; expired: number; converted: number }> {
  const out = { notices: 0, expired: 0, converted: 0 };
  const grants = await db.partnerGrant.findMany({
    where: { status: { in: ["ACTIVE", "EXPIRING"] } },
    include: { partner: { include: { user: { select: { id: true, email: true, name: true } } } } },
  });
  for (const g of grants) {
    const server = g.serverId ? await db.server.findUnique({ where: { id: g.serverId }, select: { id: true, expiresAt: true, status: true, hostname: true, gamePlan: { select: { priceCents: true, termMonths: true } }, termMonths: true } }) : null;
    if (g.serverId && (!server || server.status === "DELETING")) {
      await db.partnerGrant.update({ where: { id: g.id }, data: { status: "EXPIRED", error: "server removed" } });
      out.expired++;
      continue;
    }
    const phase = grantPhase(g, server?.expiresAt ?? null, now);
    if (phase === "converted") {
      await db.partnerGrant.update({ where: { id: g.id }, data: { status: "CONVERTED", expiresAt: server?.expiresAt ?? g.expiresAt } });
      await db.auditLog.create({ data: { userId: null, action: "partner.grant_converted", detail: `grant=${g.id} server=${g.serverId}` } });
      out.converted++;
    } else if (phase === "expired") {
      await db.partnerGrant.update({ where: { id: g.id }, data: { status: "EXPIRED" } });
      await db.auditLog.create({ data: { userId: null, action: "partner.grant_expired", detail: `grant=${g.id} server=${g.serverId} onExpiry=${g.onExpiry}` } });
      out.expired++;
    } else if ((phase === "notice" || phase === "final") && g.partner.user) {
      const price = server?.gamePlan ? Math.round(server.gamePlan.priceCents / Math.max(1, server.gamePlan.termMonths)) * (server.termMonths || 1) : null;
      const sent = await sendGrantNotice({ to: g.partner.user.email, name: g.partner.user.name, game: g.game, planName: g.planName, expiresAt: g.expiresAt!, policy: g.onExpiry as GrantPolicy, priceCents: price, termMonths: server?.termMonths ?? g.termMonths, final: phase === "final", userId: g.partner.user.id, serverId: g.serverId });
      if (sent) {
        await db.partnerGrant.update({ where: { id: g.id }, data: { status: "EXPIRING", ...(phase === "final" ? { finalNoticeSentAt: now, noticeSentAt: g.noticeSentAt ?? now } : { noticeSentAt: now }) } });
        out.notices++;
      }
    }
  }
  return out;
}
// Pure grant-lifecycle rules (no DB import) — used by lib/partner-grants.ts and unit tests.
export const GRANT_NOTICE_DAYS = 7;
export const GRANT_FINAL_NOTICE_DAYS = 1;

export type GrantPhase = "none" | "notice" | "final" | "expired" | "converted";

/** Pure: where is a grant in its lifecycle? `serverExpiresAt` is the LIVE server expiry. */
export function grantPhase(
  g: { expiresAt: Date | null; noticeSentAt: Date | null; finalNoticeSentAt: Date | null },
  serverExpiresAt: Date | null, now: Date,
): GrantPhase {
  if (!g.expiresAt) return "none";
  // The server's term moved past the granted one => somebody (the partner, or the renewal sweep) paid for more.
  if (serverExpiresAt && serverExpiresAt.getTime() > g.expiresAt.getTime() + 86_400_000) return "converted";
  const msLeft = g.expiresAt.getTime() - now.getTime();
  if (msLeft <= 0) return "expired";
  if (msLeft <= GRANT_FINAL_NOTICE_DAYS * 86_400_000 && !g.finalNoticeSentAt) return "final";
  if (msLeft <= GRANT_NOTICE_DAYS * 86_400_000 && !g.noticeSentAt) return "notice";
  return "none";
}

