import type { Role, User } from "@prisma/client";
import { db } from "./db";
import { realUser } from "./auth";
import { canAccess, isStaff, type Area } from "./rbac";

/**
 * Per-employee (Role.EMPLOYEE) tool grants, layered ADDITIVELY on top of
 * lib/rbac.ts's role→area system — nothing in lib/rbac.ts changes behavior
 * for CUSTOMER/SUPPORT/BILLING/ADMIN. `canAccess`/`requireArea` there are
 * untouched; every one of their ~115 existing call sites is unaffected.
 *
 * EMPLOYEE is never listed in AREA_ROLES for any area (see lib/rbac.ts), so
 * an EMPLOYEE has ZERO access anywhere until a StaffGrant row exists for
 * them. This module is the only thing that ever reads StaffGrant, and it is
 * only ever consulted for the EMPLOYEE role — the fast path for every other
 * role is the existing, unchanged `canAccess` check with no DB hit.
 *
 * WHY A SEPARATE MODULE FROM lib/rbac.ts: keeps that file's existing,
 * heavily-relied-on exports byte-identical, so a diff against it proves this
 * feature couldn't have regressed anything already using it.
 *
 * LESSON APPLIED FROM lib/team-guard.ts's DELETION: that per-org permission
 * system was ripped out because it only ever filtered nav — no loader or
 * action actually checked it, so the "permission" was a promise the server
 * never kept. Every area opened to EMPLOYEE here is migrated at the ACTION
 * layer (see lib/actions-reddit-templates.ts, lib/actions-company-mail.ts,
 * lib/mail/imap.ts's resolveMailbox, lib/actions-support.ts's
 * requireTicketActor, lib/actions-chat.ts), not just its page.
 */

export async function hasAreaAccess(user: Pick<User, "id" | "role">, area: Area): Promise<boolean> {
  if (canAccess(user.role, area)) return true;
  if (user.role !== "EMPLOYEE") return false;
  const grant = await db.staffGrant.findUnique({
    where: { userId_area: { userId: user.id, area } },
    select: { id: true },
  });
  return !!grant;
}

export async function hasAnyAreaAccess(user: Pick<User, "id" | "role">, areas: Area[]): Promise<boolean> {
  for (const area of areas) {
    if (await hasAreaAccess(user, area)) return true;
  }
  return false;
}

/** Server-action guard. Throws UNAUTHORIZED/FORBIDDEN — never redirects. */
export async function requireGrant(area: Area): Promise<User> {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role === "CUSTOMER") throw new Error("FORBIDDEN");
  if (!(await hasAreaAccess(user, area))) throw new Error("FORBIDDEN");
  return user;
}

