export type FleetTagTone = "brand" | "green" | "red" | "amber" | "slate";
export type FleetTag = { key: string; tone: FleetTagTone; label: string; title?: string };

/** The columns a fleet-list row needs to derive its lifecycle/add-on tags. */
export type FleetTagServer = {
  status: string;
  isFree: boolean;
  expiresAt: Date | null;
  suspendReason: string | null;
  grandfatheredRenewalCents: number | null;
  extraDiskGB: number;
  backupTier: string;
  wantsDedicatedIp: boolean;
  dedicatedIp: unknown | null;
  // Needed ONLY to tell an actually-frozen-below-market rate apart from the
  // routine "freeze the rate you were sold at" write every order/resize makes
  // (lib/order.ts, lib/game-order.ts, worker/index.ts) — that write sets
  // grandfatheredRenewalCents on basically every server, so a plain `!= null`
  // check tagged nearly the whole fleet "Grandfathered", including brand-new
  // customers on today's live pricing (caught 2026-09-25: the owner screenshotted
  // the fleet list and pointed out most rows tagged weren't actually on old
  // pricing).
  plan: { priceCents: number };
  gamePlan: { priceCents: number; termMonths: number } | null;
};

/**
 * Small, scannable per-server tags for the fleet list. Every condition is
 * lifted from an existing, real definition elsewhere in the codebase rather
 * than invented fresh here — see each branch's comment for where it comes
 * from — so a tag can never disagree with the mechanism it describes.
 */
export function serverFleetTags(
  s: FleetTagServer,
  opts: {
    now: Date;
    /** "Renewing soon" window, in ms. Reuse an existing convention — see caller. */
    renewingSoonWindowMs: number;
    /**
     * The real dunning config (lib/dunning-config.ts — the exact function
     * worker/billing.ts's sweep uses), or null to skip the "Deleting soon"
     * computation entirely (e.g. the caller already knows no suspended-unpaid
     * rows exist and didn't bother fetching it).
     */
    dunning: DunningConfig | null;
  },
): FleetTag[] {
  const tags: FleetTag[] = [];
  const nowMs = opts.now.getTime();

  if (s.grandfatheredRenewalCents != null) {
    const livePlanMonthlyCents = s.gamePlan
      ? monthlyCents(s.gamePlan.priceCents, s.gamePlan.termMonths)
      : s.plan.priceCents;
    const effectivePlanMonthlyCents = s.gamePlan
      ? monthlyCents(s.grandfatheredRenewalCents, s.gamePlan.termMonths)
      : s.grandfatheredRenewalCents;
    // DIRECTION MATTERS (caught 2026-09-25 via the owner's fleet screenshot:
    // web-01-oyrj and minecraft-qj4rxt were tagged "Grandfathered" while
    // locked ABOVE today's live rate — the owner's own words, "we dont
    // qualify them for the grandfathered pricing"). "Grandfathered" is a
    // customer-favorable claim — protection from a price INCREASE — so it
