  runtime?: RuntimeView | null;
  /** literal ip:port for clients that can't resolve the Minecraft SRV subdomain */
  directConnect?: string | null;
  /** ip:port players connect to, or null while provisioning */
  connect: string | null;
  /** short server id badge, e.g. "#srv_8f7a2c1d" */
  serverIdShort: string;
