/**
 * Batched data loader for lib/server-ownership-tags.ts: two queries for ANY number of
 * servers (PartnerGrant by serverId, ReferralPartner by owner userId) — never per row.
 */
import { db } from "./db";
import { serverOwnershipTags, type OwnershipInput, type OwnershipTag } from "./server-ownership-tags";

export type TagServerRef = { id: string; userId: string; isFree: boolean; expiresAt: Date | null };

export async function loadOwnershipTags(servers: TagServerRef[], now: Date = new Date()): Promise<Map<string, OwnershipTag[]>> {
  const out = new Map<string, OwnershipTag[]>();
  if (servers.length === 0) return out;
  const ids = servers.map((s) => s.id);
  const userIds = [...new Set(servers.filter((s) => s.isFree).map((s) => s.userId))];
  const [grants, partners] = await Promise.all([
    db.partnerGrant.findMany({
      where: { serverId: { in: ids } },
      select: { serverId: true, status: true, expiresAt: true, noticeSentAt: true, finalNoticeSentAt: true },
    }),
    userIds.length
      ? db.referralPartner.findMany({ where: { userId: { in: userIds } }, select: { userId: true } })
      : Promise.resolve([] as { userId: string | null }[]),
  ]);
  const grantByServer = new Map(grants.map((g) => [g.serverId as string, g]));
  const partnerUsers = new Set(partners.map((p) => p.userId));
  for (const s of servers) {
    const input: OwnershipInput = {
      isFree: s.isFree,
      serverExpiresAt: s.expiresAt,
      grant: grantByServer.get(s.id) ?? null,
      ownerIsPartner: partnerUsers.has(s.userId),
    };
    out.set(s.id, serverOwnershipTags(input, now));
  }
  return out;
}
