cd /opt/nxeon-wt-tags; cat > test/server-ownership-tags.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { serverOwnershipTags, isEffectivelyFree, type OwnershipInput } from "../lib/server-ownership-tags.ts";

const NOW = new Date("2026-10-01T00:00:00Z");
const DAY = 86_400_000;
const keys = (i: OwnershipInput, now = NOW) => serverOwnershipTags(i, now).map((t) => t.key);

function grant(over: Partial<NonNullable<OwnershipInput["grant"]>> = {}) {
  return { status: "ACTIVE", expiresAt: new Date(NOW.getTime() + 60 * DAY), noticeSentAt: null, finalNoticeSentAt: null, ...over };
}
function input(over: Partial<OwnershipInput> = {}): OwnershipInput {
  return { isFree: false, serverExpiresAt: new Date(NOW.getTime() + 60 * DAY), grant: null, ownerIsPartner: false, ...over };
}

test("creator grant (isFree false, sold at 0): Free + Creator while active", () => {
  assert.deepEqual(keys(input({ grant: grant(), ownerIsPartner: true })), ["free", "creator"]);
  assert.deepEqual(keys(input({ grant: grant({ status: "EXPIRING" }), ownerIsPartner: true })), ["free", "creator"]);
});

test("ordinary admin free server: Free only, no Creator", () => {
  assert.deepEqual(keys(input({ isFree: true })), ["free"]);
});

test("admin free server on a creator partner's account: Free + Creator", () => {
  assert.deepEqual(keys(input({ isFree: true, ownerIsPartner: true })), ["free", "creator"]);
});

test("paid server never shows Free, even when its owner is a partner", () => {
  assert.deepEqual(keys(input()), []);
  assert.deepEqual(keys(input({ ownerIsPartner: true })), []);
});

test("converted grant (status CONVERTED, or term paid past the grant before the sweep runs): no tags", () => {
  assert.deepEqual(keys(input({ grant: grant({ status: "CONVERTED" }), ownerIsPartner: true })), []);
  const paidPast = input({ grant: grant(), ownerIsPartner: true, serverExpiresAt: new Date(NOW.getTime() + 60 * DAY + 30 * DAY) });
  assert.deepEqual(keys(paidPast), []);
  assert.equal(isEffectivelyFree(paidPast, NOW), false);
});

test("revoked / expired / failed grants: no Creator and no Free", () => {
  for (const status of ["REVOKED", "EXPIRED", "FAILED"]) {
    assert.deepEqual(keys(input({ grant: grant({ status }), ownerIsPartner: true })), [], status);
  }
});

test("grant past its end date before the sweep marks it EXPIRED: tags drop", () => {
  const lapsed = grant({ expiresAt: new Date(NOW.getTime() - DAY) });
  assert.deepEqual(keys(input({ grant: lapsed, ownerIsPartner: true, serverExpiresAt: lapsed.expiresAt })), []);
});

test("an isFree flag still wins over a dead grant (explicit admin decision)", () => {
  assert.deepEqual(keys(input({ isFree: true, grant: grant({ status: "REVOKED" }), ownerIsPartner: true })), ["free", "creator"]);
});

test("tags carry accessible text labels and titles", () => {
  const tags = serverOwnershipTags(input({ grant: grant(), ownerIsPartner: true }), NOW);
  assert.deepEqual(tags.map((t) => t.label), ["Free", "Creator"]);
  assert.ok(tags.every((t) => t.title.length > 10));
});
EOF
